import{_ as e,o as p,c as a,y as r}from"./chunks/framework.CNTkXYA8.js";const i=JSON.parse('{"title":"【酷Q&C++】如何利用酷Q制作一个机器人？","description":"","frontmatter":{"title":"【酷Q&C++】如何利用酷Q制作一个机器人？","date":"2018-12-12T17:57:00.000Z"},"headers":[],"relativePath":"blog/q-c-q.md","filePath":"source/old_posts/q-c-q.md"}'),o={name:"blog/q-c-q.md"};function c(d,t,l,s,n,h){return p(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1><p>——酷Q Air教程</p><p>要想阅读本篇教程，读者需要基本的C++知识以及Visual Studio 2010/2015/2017</p><p>首先，需要从官方网站下载软件 <a href="https://cqp.cc/t/23253" target="_blank" rel="noreferrer">https://cqp.cc/t/23253</a> 。下载后从“下载“/”Download“文件夹中找到其压缩包。解压。</p><p>然后，我们从Github中下载酷Q的SDK。</p><p><a href="https://github.com/CoolQ/cqsdk-vc" target="_blank" rel="noreferrer">https://github.com/CoolQ/cqsdk-vc</a></p><p>解压发现.sln，是项目，使用VS打开。</p><p>使用Release编译。（这一步基本不会出现问题）</p><p>发现Release中出现了你编译出的dll。</p><p>在.\\cqsdk-vc-master\\CQPdemo中找到com.example.democ.json。里面存放你的插件运行时的菜单，权限等信息。</p><p>然后，将dll和json一起拷贝到你解压酷Q软件目录下 .\\酷Q Air\\app\\ 下。</p><p>这时打开酷Q软件，发现“应用目录“中没有我们的插件。于是我们打开开发者模式：</p><p>打开conf文件夹，找到CQP.cfg</p><p>打开CQP.cfg</p><p>在文件最后加入</p><p>[Debug]</p><p>DeveloperMode=1</p><p>然后重启酷Q。这时候可以看到我们的插件。</p><p>至此，demo制作完成。</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td></td><td></td></tr><tr><td></td><td></td></tr></tbody></table><p>以下是几个编写教程：</p><p>在每个事件函数中，SDK的demo均给了详细注释，笔者在此不再多言。</p><p>至于函数用法，这里有一篇教程：</p><p><a href="https://cqp.cc/t/28730" target="_blank" rel="noreferrer">https://cqp.cc/t/28730</a></p><p>最后，感谢酷Q开发者。</p>',25)])])}const m=e(o,[["render",c]]);export{i as __pageData,m as default};
